'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),os=require('node:os');
const {makeProfileVault}=require('../profile-vault'),{makeJigBanks}=require('../jig-address-banks'),{makeVault}=require('../local-card-vault');
const D=require('../profile-draft-core'),F=require('../jig-field-core'),Core=require('../app'),{createWorkshop}=require('../profile-workshop-service');
const event={sender:{id:1}},foreign={sender:{id:2}};
const crypto={isEncryptionAvailable:()=>true,encryptString:s=>Buffer.from('ENCRYPTED:'+s),decryptString:b=>{assert.ok(b.toString().startsWith('ENCRYPTED:'));return b.toString().slice(10);}};
const address={label:'Home',address1:'100 Example Avenue',address2:'Apt 2',city:'Sample',state:'FL',zip:'33324'};
const card={label:'Test card',number:'4242424242424242',cardholder:'Saved Holder',expMonth:'08',expYear:'2031',brand:'Visa'};
const fullCard={id:'card-a',label:'Test card',number:card.number,cardholder:card.cardholder,month:card.expMonth,year:card.expYear,type:card.brand};
const choices=(n)=>({address:!!(n&1),card:!!(n&2),name:!!(n&4)});
async function env(t){const dir=await fs.mkdtemp(path.join(os.tmpdir(),'aco-workshop-'));t.after(()=>fs.rm(dir,{recursive:true,force:true}));let unlocked=true,time=1000,allowExport=false;const writes=[];
 const profiles=makeProfileVault({baseDir:dir,safeStorage:crypto}),addresses=makeJigBanks({baseDir:dir,safeStorage:crypto});
 const personal=makeVault({baseDir:dir,safeStorage:crypto,fileName:'jig-studio-personal-cards.encrypted'}),customers=makeVault({baseDir:dir,safeStorage:crypto});
 function guard(e,scope){if(e.sender.id!==1)throw Error('Not the owner window');if(scope==='personal'&&!unlocked)throw Error('Personal locked');}
 const service=createWorkshop({profiles,addressBanks:addresses,cardVault:s=>s==='personal'?personal:customers,
  authorize:async(e,s,id)=>{guard(e,s);if(s==='aco'&&!['customer-a','customer-b'].includes(id))throw Error('Unauthorized customer');return s==='personal'?null:id;},guard,now:()=>time,
  chooseSave:async(_e,o)=>({filePath:path.join(dir,o.name)}),confirmExport:async()=>allowExport,writeFile:async(...args)=>writes.push(args)});
 const p={scope:'personal',customerId:null},a={scope:'aco',customerId:'customer-a'},b={scope:'aco',customerId:'customer-b'};
 return {dir,profiles,addresses,personal,customers,service,p,a,b,writes,lock:()=>{unlocked=false;},setTime:v=>time=v,export:()=>allowExport=true};
}

const Completion=require('../profile-completion-core');
async function ready(t,scope){const h=await env(t),owner=scope==='aco'?h.a:h.p;
 const row=await h.service.create(event,{...owner,retailer:'target',format:'shikari',fields:{email:'own@example.test',first:'Alex',last:'Example',phone:'9545550100'}});
 const a=await h.service.addAddress(event,{...owner,address}),c=await h.service.addCard(event,{...owner,card});
 const plan=await h.service.preview(event,{...owner,profileIds:[row.id],contextKey:'complete',choices:{address:true,card:true,name:true},addressIds:[a.id],cardIds:[c.id],mirrorBilling:true,addressOptions:{applyStyles:true,rules:['avenue_short']}});
 await h.service.save(event,{token:plan.token,contextKey:'complete',confirmed:true});return {h,owner,id:row.id};
}
test('Complete jigged profile automatically enters Completed Profiles with same names and phones',async t=>{const {h,owner,id}=await ready(t);const list=await h.profiles.list(owner.scope,owner.customerId),row=list.profiles[0];assert.equal(row.stage,'completed');assert.deepEqual(row.missing,[]);assert.ok(row.completedAt);const full=(await h.profiles.preview(owner.scope,owner.customerId,id)).profile;assert.equal(full.data.shipping_phone,'9545550100');assert.equal(full.data.billing_phone,'9545550100');assert.equal(full.data.shipping_first_name,full.data.billing_first_name);});
test('Missing required details keep profile in progress; removing a phone reopens completed profile',async t=>{const {h,owner,id}=await ready(t);const original=(await h.profiles.preview(owner.scope,owner.customerId,id)).profile,v=D.toValues(original.data);v.phone='';v['shipping.phone']='';v['billing.phone']='';await h.service.edit(event,{...owner,profileId:id,revision:original.revision,fields:v});const row=(await h.profiles.list(owner.scope,owner.customerId)).profiles[0];assert.equal(row.stage,'in-progress');assert.ok(row.missing.includes('Shipping phone number'));v.phone='9545550101';const next=(await h.profiles.preview(owner.scope,owner.customerId,id)).profile;await h.service.edit(event,{...owner,profileId:id,revision:next.revision,fields:v});assert.equal((await h.profiles.list(owner.scope,owner.customerId)).profiles[0].stage,'completed');});
test('A fully populated profile does not require a saved jig marker',()=>{const data=D.blank('target','shikari',{email:'own@example.test',first:'Alex',last:'Example',phone:'9545550100','shipping.address1':'100 Example Ave','shipping.city':'Example','shipping.state':'FL','shipping.zip':'33324','billing.address1':'100 Example Ave','billing.city':'Example','billing.state':'FL','billing.zip':'33324'});Object.assign(data,{cc_number:card.number,cc_name:card.cardholder,cc_exp_month:'08',cc_exp_year:'2031'});assert.equal(Completion.inspect({data}).ready,true);assert.doesNotMatch(Completion.inspect({data}).missing.join(' '),/Saved jig/);});
test('Explicit full card view returns number only from authorized selected vault',async t=>{const {h,owner}=await ready(t);const full=await h.service.assets(event,{...owner,showFullCards:true});assert.equal(full.cards[0].number,card.number);assert.equal(full.cards[0].expYear,'2031');assert.equal(full.cards[0].unused,false);assert.equal((await h.service.assets(event,{...h.a,showFullCards:true})).cards.length,0);h.lock();await assert.rejects(h.service.assets(event,{...owner,showFullCards:true}),/locked/);});
test('Customer completion stays separate from private and other customer profiles',async t=>{const {h,owner,id}=await ready(t,'aco');assert.equal((await h.profiles.list('aco',owner.customerId)).profiles[0].stage,'completed');assert.equal((await h.profiles.list('aco',h.b.customerId)).profiles.length,0);assert.equal((await h.profiles.list('personal',null)).profiles.length,0);await assert.rejects(h.profiles.preview('aco',h.b.customerId,id),/not found/);await assert.rejects(h.service.assets(foreign,{...owner,showFullCards:true}));});
test('Valor requires complete names/address/phones/card and jig without requiring a password',()=>{const data=D.blank('walmart','valor',{email:'valor@example.test',first:'Alex',last:'Example',phone:'9545550100','shipping.address1':'100 Example Ave','shipping.city':'Example','shipping.state':'FL','shipping.zip':'33324','billing.address1':'100 Example Ave','billing.city':'Example','billing.state':'FL','billing.zip':'33324'});Object.assign(data.card,{number:card.number,holder:card.cardholder,expiration:'08/31'});assert.equal(Completion.inspect({data,jiggedAt:'now'}).ready,true);data.card.expiration='13/31';assert.ok(Completion.inspect({data,jiggedAt:'now'}).missing.includes('Card expiration'));});
